-- ===== Series 88J (42 products, quote-only Price NULL) =====
IF NOT EXISTS (SELECT 1 FROM Categories WHERE Name = N'Series 88J')
    INSERT INTO Categories (Name, Description, BodyMaterial, SeatMaterial, Design, Approvals, KeyFeatures)
    VALUES (N'Series 88J', N'The Mars Series 88J is a 3-piece, full-port steam-jacketed direct-mount ball valve, rated to 2000 PSI and certified to API 607 (7th Edition). CF8M body with 25% carbon+PTFE seats and an SS304 jacketed part (threaded NPT/BSP), in sizes 1/4" to 1 1/2". Ends: threaded, butt weld, socket weld, flanged, extended BW or ISO orbital welding.', N'CF8M', N'25% Carbon + PTFE', N'Three Piece, Steam Jacketed, Full Port, Direct Mount', N'Fire-Safe API 607, 7th Edition', N'3-piece steam jacketed full port design
Direct mount
SS304 jacketed part (threaded NPT/BSP)
Ends: Threaded, Butt Weld, Socket Weld, Flanged, Extended BW, ISO Orbital Welding
Rated to 2000 PSI
CF8M body
25% carbon + PTFE seats
Size 1/4" to 1 1/2"
Fire-safe API 607, 7th Edition');
GO
DECLARE @SeriesName nvarchar(100) = N'Series 88J';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);
INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'Size'),(N'End Connection'),(N'Operating Pressure')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);
INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder FROM (VALUES (N'End Connection',0),(N'Size',1),(N'Operating Pressure',2)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);
